  const editKey = key => (newFormat() && (['관계·감정선', '호칭·말투'].includes(key) || (key === '인지·비밀' && !factsNew())) ? '인물' : key);

  const splitNames = t => t.split(/\s*(?:\/|·|,|、|&|그리고|및)\s*/).map(x => x.trim()).filter(Boolean);
