  const devSeg = () => `<div class="seg devseg">${DEVICES.map(([k, l]) => `<button data-act="dev" data-arg="${k}" aria-pressed="${(nav.dev || 'phone') === k}">${l}</button>`).join('')}</div>`;

  // ── 💻 컴퓨터: 폰처럼 버튼을 눌렀을 때만 AI 1번, 결과는 이 브라우저에만 ──
  const PC_PROMPT = unveil('');
