  const rvStart = () => nav.rvPick ? '' : `<button class="rv-start" data-act="rvpick"${busyNow || noFullHere() ? ' disabled' : ''} title="${noFullHere() ? '이 기기엔 전체 기억이 없어서 못 해요' : '고른 기억을 원문과 다시 맞춰 봐요'}">🔍 다시 확인</button>`;
