      let ring = 3;
      comp.filter(n => !local.has(n)).forEach((n, i) => local.set(n, { x: (i - 1) * 90, y: R2 + 120, ring }));
      const xs = [...local.values()].map(p => p.x), minX = Math.min(...xs), maxX = Math.max(...xs);
      const shift = offsetX === null ? 0 : offsetX - minX + 110;
