      if (k.split('\u0000').includes(root)) continue; // 가운데 부부의 아이는 가족 중심 배치에서 이미 아래에
      const [a, b] = k.split('\u0000').map(x => pos.get(x)), mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2, len = Math.hypot(b.x - a.x, b.y - a.y) || 1, ux = (b.x - a.x) / len, uy = (b.y - a.y) / len;
