    const norm = m => cleanLog(msgText(m), msgRole(m) !== 'user').replace(/\s+/g, ''), upTo = src.slice(0, k + 1), turn = upTo.filter(m => msgRole(m) === 'user').length; if (!turn) return null;
    let u = k; while (u >= 0 && msgRole(src[u]) !== 'user') u--;
